using GSS.Api.Extensions.Core;
using GSS.Api.Helpers;

namespace GSS.Api.Extensions.Features;

/// <summary>
/// OpenAPI document and Swagger UI.
/// </summary>
public static class OpenApiExtensions
{
    /// <summary>Swagger UI route prefix.</summary>
    public const string SwaggerUiPath = "/swagger";

    /// <summary>OpenAPI document generated by Microsoft.AspNetCore.OpenApi.</summary>
    private const string OpenApiDocumentPath = "/openapi/v1.json";

    /// <summary>Swagger UI loads its own scripts and sets inline styles; the API-wide CSP (<c>default-src 'none'</c>) would blank it.</summary>
    private const string SwaggerUiContentSecurityPolicy =
        "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; frame-ancestors 'none'";

    /// <summary>
    /// Registers OpenAPI services: the configured title and request examples. Paths need no rewriting: the versioned
    /// API Explorer (<c>SubstituteApiVersionInUrl</c>) already emits <c>/api/v1/...</c> without a version parameter.
    /// </summary>
    public static void ConfigureOpenApi(this IServiceCollection services)
    {
        services.AddOpenApi(options =>
        {
            options.AddDocumentTransformer<ApiTitleDocumentTransformer>();
            options.AddSchemaTransformer<RequestExampleSchemaTransformer>();
            options.AddOperationTransformer<MultipleOkResponsesOperationTransformer>();
            options.AddOperationTransformer<ApiSecurityOperationTransformer>();
        });
    }

    /// <summary>Maps the OpenAPI document outside Production.</summary>
    public static void ConfigureOpenApiEndpoints(this WebApplication app)
    {
        if (!app.Configuration.IsProductionEnvironment())
        {
            app.MapOpenApi().AllowAnonymous();
        }
    }

    /// <summary>
    /// Serves Swagger UI at <c>/swagger</c> outside Production, with its own CSP. It is middleware, not an endpoint,
    /// so it must run before authorization (the fallback policy would answer 401).
    /// </summary>
    public static void UseSwaggerUiIfEnabled(this IApplicationBuilder app, IConfiguration configuration)
    {
        if (configuration.IsProductionEnvironment())
        {
            return;
        }

        // The security headers phase keeps a header already set.
        app.Use((context, next) =>
        {
            if (context.Request.Path.StartsWithSegments(SwaggerUiPath, StringComparison.OrdinalIgnoreCase))
            {
                context.Response.Headers.ContentSecurityPolicy = SwaggerUiContentSecurityPolicy;
            }

            return next(context);
        });

        string title = ApiTitleDocumentTransformer.GetApiTitle(configuration);
        app.UseSwaggerUI(options =>
        {
            options.RoutePrefix = SwaggerUiPath.TrimStart('/');
            options.SwaggerEndpoint(OpenApiDocumentPath, string.IsNullOrWhiteSpace(title) ? "v1" : title);
            options.DocumentTitle = string.IsNullOrWhiteSpace(title) ? "GSS API" : title;

            // No call to the public swagger.io validator.
            options.ConfigObject.ValidatorUrl = "none";
        });
    }
}
